pair<i64, vector<int>> maxClosure(const vector<i64>& w, const vector<pair<int, int>>& dep) {
    int n = int(w.size()) - 1, s = 0, t = n + 1;
    Dinic f(n + 2);
    i64 sum = 0;
    for(int u = 1; u <= n; u++) {
        if(w[u] > 0) {
            sum += w[u];
        }
    }
    assert(sum < LLONG_MAX / 4);
    for(int u = 1; u <= n; u++) {
        if(w[u] > 0) {
            f.addEdge(s, u, w[u]);
        }
        if(w[u] < 0) {
            f.addEdge(u, t, -w[u]);
        }
    }
    for(auto [u, v] : dep) {
        f.addEdge(u, v, sum + 1);
    }
    i64 ans = sum - f.maxFlow(s, t);
    auto vis = f.minCut(s);
    vector<int> chosen;
    for(int u = 1; u <= n; u++) {
        if(vis[u]) {
            chosen.push_back(u);
        }
    }
    return {ans, chosen};
}

