struct LinearSieve {
    int n;
    vector<int> primes, minp, phi, mu;
    LinearSieve(int n_ = 0) : n(n_), minp(n_ + 1), phi(n_ + 1), mu(n_ + 1) {
        if(n < 1) {
            return;
        }
        phi[1] = 1;
        mu[1] = 1;
        for(int i = 2; i <= n; i++) {
