        return i64((u128(x) * x + u64(c)) % u64(n));
    }
    static i64 pollard(i64 n, mt19937_64& rng) {
        if(n % 2 == 0) {
            return 2;
        }
        while(true) {
            i64 c = i64(rng() % (n - 1)) + 1;
            i64 x = i64(rng() % (n - 1)) + 1;
            i64 y = x;
            i64 d = 1;
            while(d == 1) {
                x = f(x, c, n);
                y = f(f(y, c, n), c, n);
                i64 diff = x > y ? x - y : y - x;
