template <class T> vector<Point<T>> convexHull(vector<Point<T>> p) {
    sort(p.begin(), p.end());
    p.erase(unique(p.begin(), p.end()), p.end());
    int n = int(p.size());
    if(n <= 2) {
        return p;
    }
    sort(p.begin(), p.end());
    vector<Point<T>> h;
    for(int i = 0; i < n; i++) {
        while(int(h.size()) >= 2 &&
              cross(h.back() - h[int(h.size()) - 2], p[i] - h.back()) <= 0) {
            h.pop_back();
        }
        h.push_back(p[i]);
    }
    int k = int(h.size());
    for(int i = n - 2; i >= 0; i--) {
        while(int(h.size()) > k &&
              cross(h.back() - h[int(h.size()) - 2], p[i] - h.back()) <= 0) {
            h.pop_back();
        }
        h.push_back(p[i]);
    }
    h.pop_back();
    return h;
}
// 多边形面积（鞋带公式，逆时针为正）。
template <class T> db polygonArea(const vector<Point<T>>& p) {
    db area = 0;
    int n = int(p.size());
    for(int i = 0; i < n; i++) {
        area += db(cross(p[i], p[(i + 1) % n]));
    }
    return area / 2.0;
}

