template <class T> bool pointInPolygon(const Point<T>& a, const vector<Point<T>>& p) {
    int n = int(p.size());
    for(int i = 0; i < n; i++) {
        if(onSeg(a, Line(p[i], p[(i + 1) % n]))) {
            return true;
        }
    }
    int t = 0;
    for(int i = 0; i < n; i++) {
        Point<T> u = p[i];
        Point<T> v = p[(i + 1) % n];
        if(u.x < a.x && v.x >= a.x && onLeft(a, Line(v, u))) {
            t ^= 1;
        }
        if(u.x >= a.x && v.x < a.x && onLeft(a, Line(u, v))) {
            t ^= 1;
        }
    }
    return t == 1;
}

